class Agent {
  constructor() {
    let x = R.random_num(margin, width - margin);
    let y = R.random_num(margin, height - margin);
    this.pos = createVector(x, y);

  if (sizeBool){
  this.size = R.random_int(10,100);
  }
  else{
  this.size = 10;
  }
    this.speed = R.random_num(3, 8);
    this.col = selectedColors[R.random_int(0, selectedColors.length-1)];
    this.dir = R.random_dec() > 0.5 ? 1 : -1;
  }

  style() {
    strokeWeight(this.size);
    stroke(this.col);
    noFill();
  }

  display() {
    this.style();
    point(this.pos.x, this.pos.y);
  }

  update() {
    let angle = noise(this.pos.x / noiseScale, this.pos.y / noiseScale) * noiseStrength;

    if (tanRand) {
      this.pos.x += tan(angle) * this.speed * this.dir;
      this.pos.y += cos(angle) * this.speed * this.dir;
    } else {
      this.pos.x += sin(angle) * sinMult * this.speed * this.dir;
      this.pos.y += cos(angle) * this.speed * this.dir;
    }



    this.bounds();
  }

  bounds() {
    if (
      this.pos.x < margin ||
      this.pos.y < margin ||
      this.pos.x > width - margin ||
      this.pos.y > height - margin
    ) {
      this.dir = -this.dir;
    }

    this.pos.x = constrain(this.pos.x, margin, width - margin);
    this.pos.y = constrain(this.pos.y, margin, height - margin);
  }

  updateColor() {
    this.col = selectedColors[R.random_int(0, selectedColors.length-1)];
  }

  updateSizeAndSpeed() {
    this.size = R.random_int(10, 60);
    this.speed = R.random_num(0.5, 4);
  }
}
